"""
A very small, safe "migration" helper.

SQLAlchemy's create_all() can CREATE new tables, but it will never ADD a
new column to a table that already exists. So when we add a field to a
model, an existing app.db would keep the old shape and every query would
fail with "no such column".

This runs on startup, looks at what columns each table actually has, and
adds any that are missing. It never drops or rewrites anything, so no
existing data is lost.
"""

from sqlalchemy import inspect, text


def _existing_columns(connection, table_name):
    return {row[1] for row in connection.execute(text(f"PRAGMA table_info({table_name})"))}


def run_migrations(engine):
    # table -> {column name: SQL type to add it with}
    wanted = {
        "users": {
            "security_question": "VARCHAR",
            "security_answer_hash": "VARCHAR",
        },
    }

    inspector = inspect(engine)
    existing_tables = set(inspector.get_table_names())

    with engine.begin() as connection:
        for table, columns in wanted.items():
            if table not in existing_tables:
                continue  # create_all() will build it fresh with every column
            have = _existing_columns(connection, table)
            for column, sql_type in columns.items():
                if column not in have:
                    connection.execute(text(f"ALTER TABLE {table} ADD COLUMN {column} {sql_type}"))
                    print(f"[migration] added column {table}.{column}")

from fastapi import APIRouter, Depends, HTTPException, UploadFile, File, Form
from fastapi.responses import Response

from app.models.user import User
from app.routes.deps import get_current_user
from app.services.image_service import process_image, background_removal_status
from app.services import gemini_image_service, openai_image_service

router = APIRouter(prefix="/image", tags=["Image Enhancement"])
ALLOWED_TYPES = {"image/jpeg", "image/png", "image/webp"}


def _header_safe(text: str) -> str:
    """HTTP headers must be plain ASCII. Error text can contain quotes,
    newlines or non-English characters, so clean it before sending."""
    if not text:
        return ""
    cleaned = " ".join(str(text).split())
    return cleaned.encode("ascii", "ignore").decode("ascii")[:300]


@router.get("/capabilities")
def capabilities():
    """
    Tells the frontend exactly which photo engines are really available,
    so the app can be honest on screen instead of guessing.

    OpenAI is preferred first now (see config.py's provider comment -
    the user is buying OpenAI credits specifically for this hackathon),
    Gemini second as a free fallback, then the always-available local
    engine last.
    """
    local_available, local_reason = background_removal_status()
    openai_available = openai_image_service.is_configured()
    gemini_available = gemini_image_service.is_configured()
    if openai_available:
        default_engine = "openai"
    elif gemini_available:
        default_engine = "gemini"
    else:
        default_engine = "local"
    return {
        "openai_available": openai_available,
        "gemini_available": gemini_available,
        "background_removal_available": local_available,
        "unavailable_reason": local_reason,
        "default_engine": default_engine,
    }


@router.post("/enhance")
def enhance(
    image: UploadFile = File(...),
    engine: str = Form("auto"),
    remove_bg: bool = Form(False),
    brightness: float = Form(1.15),
    contrast: float = Form(1.15),
    instruction: str = Form(""),
    current_user: User = Depends(get_current_user),
):
    """
    Runs the AI Product Photo Studio.

    engine:
      "auto"   - use OpenAI if configured, else Gemini, else work locally
      "openai" - real AI re-shoot of the photo via OpenAI (needs OPENAI_API_KEY)
      "gemini" - real AI re-shoot of the photo via Gemini (needs AI_API_KEY)
      "local"  - local background removal + brightness/contrast/sharpness

    If the AI engine fails for any reason we do NOT show an error page and
    lose the artisan's work - we quietly fall back to the local engine and
    report honestly in the response headers what actually ran.
    """
    if image.content_type not in ALLOWED_TYPES:
        raise HTTPException(status_code=400, detail="Only JPG, PNG or WEBP images are allowed.")

    contents = image.file.read()
    if not contents:
        raise HTTPException(status_code=400, detail="That image file appears to be empty.")

    engine = (engine or "auto").lower()
    if engine == "auto":
        if openai_image_service.is_configured():
            engine = "openai"
        elif gemini_image_service.is_configured():
            engine = "gemini"
        else:
            engine = "local"

    note = ""

    # ---- Real AI path (OpenAI) -----------------------------------------
    if engine == "openai":
        processed, content_type, error = openai_image_service.enhance_product_photo(
            contents, extra_instruction=instruction
        )
        if processed is not None:
            headers = {
                "X-Enhance-Engine": "openai",
                "X-Enhance-Note": _header_safe("Enhanced by OpenAI product photography."),
                "X-Background-Removed-Real-Ai": "true",
            }
            return Response(content=processed, media_type=content_type, headers=headers)

        # OpenAI failed - try the free Gemini key next (if any) before
        # falling all the way back to the local engine, so a temporary
        # OpenAI quota/billing hiccup doesn't waste a perfectly good
        # second AI provider that's already configured.
        if gemini_image_service.is_configured():
            engine = "gemini"
            note = f"OpenAI enhancement unavailable, trying Gemini instead. Reason: {error}"
        else:
            note = f"AI enhancement unavailable, used the local engine instead. Reason: {error}"

    # ---- Real AI path (Gemini) ------------------------------------------
    if engine == "gemini":
        processed, content_type, error = gemini_image_service.enhance_product_photo(
            contents, extra_instruction=instruction
        )
        if processed is not None:
            headers = {
                "X-Enhance-Engine": "gemini",
                "X-Enhance-Note": _header_safe(note or "Enhanced by Gemini AI product photography."),
                "X-Background-Removed-Real-Ai": "true",
            }
            return Response(content=processed, media_type=content_type, headers=headers)

        # Fell through - say why, then carry on with the local engine.
        note = f"AI enhancement unavailable, used the local engine instead. Reason: {error}"

    # ---- Local path ---------------------------------------------------
    processed, content_type, used_real_bg_ai = process_image(
        contents, remove_bg=remove_bg, brightness=brightness, contrast=contrast
    )

    if not note:
        note = (
            "Background removed locally and photo enhanced."
            if used_real_bg_ai
            else "Photo enhanced with brightness, contrast and sharpness."
        )

    headers = {
        "X-Enhance-Engine": "local-ai" if used_real_bg_ai else "basic",
        "X-Enhance-Note": _header_safe(note),
        "X-Background-Removed-Real-Ai": "true" if used_real_bg_ai else "false",
    }
    return Response(content=processed, media_type=content_type, headers=headers)

from fastapi import APIRouter, Depends
from sqlalchemy.orm import Session

from app.database.db import get_db
from app.models.user import User
from app.schemas.user import UserOut, UpdateProfileRequest
from app.routes.deps import get_current_user

router = APIRouter(prefix="/users", tags=["Users"])


@router.get("/me", response_model=UserOut)
def get_me(current_user: User = Depends(get_current_user)):
    return current_user


@router.put("/me", response_model=UserOut)
def update_me(
    data: UpdateProfileRequest,
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    if data.name is not None:
        current_user.name = data.name
    if data.email is not None:
        current_user.email = data.email
    if data.preferred_language is not None:
        current_user.preferred_language = data.preferred_language

    business = current_user.business
    if business:
        if data.business_name is not None:
            business.business_name = data.business_name
        if data.craft_category is not None:
            business.craft_category = data.craft_category
        if data.description is not None:
            business.description = data.description
        if data.location is not None:
            business.location = data.location
        if data.state is not None:
            business.state = data.state

    db.commit()
    db.refresh(current_user)
    return current_user

import bcrypt
from datetime import datetime, timedelta
from jose import jwt, JWTError
from app.config import SECRET_KEY, ALGORITHM, ACCESS_TOKEN_EXPIRE_MINUTES


def hash_password(password: str) -> str:
    """Turn a plain-text password into a scrambled hash that's safe to store."""
    return bcrypt.hashpw(password.encode("utf-8"), bcrypt.gensalt()).decode("utf-8")


def verify_password(password: str, password_hash: str) -> bool:
    """Check a plain-text password against a stored hash."""
    return bcrypt.checkpw(password.encode("utf-8"), password_hash.encode("utf-8"))


def create_access_token(user_id: int) -> str:
    """
    Create a JWT (JSON Web Token): a signed piece of text that proves
    "this user logged in successfully" without the backend needing to
    remember a session. The frontend stores this and sends it back on
    every request that needs to know who's logged in.
    """
    expire = datetime.utcnow() + timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)
    payload = {"sub": str(user_id), "exp": expire}
    return jwt.encode(payload, SECRET_KEY, algorithm=ALGORITHM)


def decode_access_token(token: str):
    """Reverse of create_access_token. Returns the user id, or None if invalid/expired."""
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        return int(payload.get("sub"))
    except JWTError:
        return None


def _normalise_answer(answer: str) -> str:
    """
    Security answers are compared forgivingly: we ignore capital letters
    and extra spaces, so "Sunita  Devi", "sunita devi" and " SUNITA DEVI "
    all count as the same answer. People should not be locked out of
    their livelihood because of a stray space.
    """
    return " ".join(answer.strip().lower().split())


def hash_security_answer(answer: str) -> str:
    """Store the answer scrambled, exactly like a password - so even
    someone reading the database cannot see it."""
    return bcrypt.hashpw(_normalise_answer(answer).encode("utf-8"), bcrypt.gensalt()).decode("utf-8")


def verify_security_answer(answer: str, answer_hash: str) -> bool:
    """Check a typed answer against the stored hash."""
    if not answer_hash:
        return False
    return bcrypt.checkpw(_normalise_answer(answer).encode("utf-8"), answer_hash.encode("utf-8"))

"""
The list of security questions an artisan can choose from when
registering. Kept in ONE place on the backend so the register screen and
the forgot-password screen can never drift out of sync.

Chosen deliberately for our users: things a person remembers for life,
that don't need literacy or documents to answer, and that make sense for
artisans in rural India. Each one carries a Hindi translation so the
question can be shown in the user's own language.
"""

SECURITY_QUESTIONS = [
    {
        "id": "mother_name",
        "question_en": "What is your mother's name?",
        "question_hi": "आपकी माता जी का नाम क्या है?",
    },
    {
        "id": "birth_village",
        "question_en": "What is the name of your birth village or town?",
        "question_hi": "आपके जन्म गाँव या शहर का नाम क्या है?",
    },
    {
        "id": "first_craft",
        "question_en": "Which craft did you learn first?",
        "question_hi": "आपने सबसे पहले कौन सा शिल्प सीखा था?",
    },
    {
        "id": "favourite_festival",
        "question_en": "What is your favourite festival?",
        "question_hi": "आपका पसंदीदा त्योहार कौन सा है?",
    },
    {
        "id": "first_teacher",
        "question_en": "What is the name of the person who taught you your craft?",
        "question_hi": "आपको शिल्प सिखाने वाले व्यक्ति का नाम क्या है?",
    },
    {
        "id": "childhood_friend",
        "question_en": "What is your childhood best friend's name?",
        "question_hi": "आपके बचपन के सबसे अच्छे दोस्त का नाम क्या है?",
    },
]

VALID_QUESTION_IDS = {q["id"] for q in SECURITY_QUESTIONS}


def get_question(question_id: str):
    """Look up one question by its id. Returns None if the id is unknown."""
    for q in SECURITY_QUESTIONS:
        if q["id"] == question_id:
            return q
    return None

@echo off
echo ============================================
echo ShilpSetu - Free stuck ports (5180 / 8010)
echo ============================================
echo.
echo This happens when a previous frontend/backend window was
echo closed with the X button instead of properly stopped, and
echo Windows left the process running in the background even
echo though the window is gone.
echo.

set FOUND=0
for /f "tokens=5" %%a in ('netstat -aon ^| findstr :5180 ^| findstr LISTENING') do (
    echo Found a leftover process on port 5180 (PID %%a) - closing it...
    taskkill /F /PID %%a >nul 2>&1
    set FOUND=1
)
for /f "tokens=5" %%a in ('netstat -aon ^| findstr :8010 ^| findstr LISTENING') do (
    echo Found a leftover process on port 8010 (PID %%a) - closing it...
    taskkill /F /PID %%a >nul 2>&1
    set FOUND=1
)

if "%FOUND%"=="1" (
    echo.
    echo Done - ports 5180 and 8010 are now free.
) else (
    echo.
    echo Nothing was using 5180 or 8010 - they were already free.
)
echo.
echo You can now double-click start_project.bat
pause

