// A minimal service worker - the piece of technology that lets a
// website be "installed" like an app and gives the browser a hook for
// offline behavior. This one is deliberately simple: it lets the
// browser install ShilpSetu as an app, and provides basic protection
// if the network drops mid-request. Full offline caching of every
// screen is a later refinement (once the app is built for production
// in Phase 16), not needed for local development.
self.addEventListener('install', () => {
  self.skipWaiting()
})

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim())
})

self.addEventListener('fetch', (event) => {
  // Network-first: always try to load the latest version. Only falls
  // back to a cached copy if the network request fails entirely.
  event.respondWith(
    fetch(event.request).catch(() => caches.match(event.request))
  )
})

import { Link, useLocation } from 'react-router-dom'

// Floating "+" button - the fastest way to add a new product from
// anywhere in the app, instead of navigating to Products first and
// looking for the right button there.
export default function AddFab() {
  const location = useLocation()
  if (location.pathname === '/products') return null // already on the add/list screen

  return (
    <Link
      to="/products?new=1"
      aria-label="Add a new product"
      className="fixed right-4 bottom-20 z-20 w-14 h-14 rounded-full flex items-center justify-center text-white text-3xl font-light shadow-lg active:scale-95 transition"
      style={{ background: 'linear-gradient(135deg, #C96B4B 0%, #B8923F 50%, #6E4A8E 100%)' }}
    >
      +
    </Link>
  )
}

