  const [productId, setProductId] = useState('')
  const [messages, setMessages] = useState([])
  const [input, setInput] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const bottomRef = useRef(null)

  useEffect(() => {
    listProducts(token).then(setProducts).catch(() => {})
  }, [token])

  useEffect(() => {
    getChatHistory(token, productId || undefined)
      .then((history) => setMessages(history.map((m) => ({ role: m.role, text: m.message }))))
      .catch(() => {})
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [productId])

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  async function sendMessage(text) {
    const message = text ?? input
    if (!message.trim()) return

    setMessages((prev) => [...prev, { role: 'user', text: message }])
    setInput('')
    setError('')
    setLoading(true)
    try {
      const data = await sendBusinessMessage({ message, product_id: productId || undefined }, token)
      setMessages((prev) => [...prev, { role: 'assistant', text: data.reply, aiMode: data.ai_mode, aiProviderLabel: data.ai_provider_label }])
    } catch (err) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="flex flex-col" style={{ minHeight: 'calc(100vh - 64px - 64px)' }}>
      <div className="p-3 bg-white border-b border-gray-200">
        <label className="text-xs text-gray-500 block mb-1">Talking about (optional)</label>
        <select
          className="w-full p-2 rounded-lg border border-gray-300 text-sm"
          value={productId}
          onChange={(e) => setProductId(e.target.value)}
        >
          <option value="">General business advice</option>
          {products.map((p) => (
            <option key={p.id} value={p.id}>{p.name}</option>
          ))}
        </select>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-3">
        {messages.length === 0 && (
          <p className="text-center text-gray-400 text-sm mt-6">
            👋 Ask me anything about promoting, pricing or selling your craft.
          </p>
        )}

        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div
              className={`max-w-[80%] rounded-2xl px-4 py-2 text-sm ${
                m.role === 'user' ? 'bg-forest text-white' : 'bg-white shadow-sm text-charcoal'
              }`}
            >
              {m.text}
              {m.role === 'assistant' && m.aiMode === 'demo' && (
                <p className="text-[10px] text-sand font-semibold mt-1">Demo Mode reply</p>
              )}
              {m.role === 'assistant' && m.aiMode === 'real' && m.aiProviderLabel && (
                <p className="text-[10px] text-gray-400 mt-1">Answered by {m.aiProviderLabel}</p>
              )}
            </div>
          </div>
        ))}
        <div ref={bottomRef} />
      </div>

      <div className="p-3 bg-white border-t border-gray-200">
        <div className="flex gap-2 overflow-x-auto pb-2 mb-2">
          {SUGGESTED_QUESTIONS.map((q) => (
            <button
              key={q}
              onClick={() => sendMessage(q)}
              className="whitespace-nowrap text-xs bg-ivory border border-sand text-charcoal px-3 py-1.5 rounded-full"
            >
              {q}
            </button>
          ))}
        </div>

        {error && <p className="text-red-600 text-xs mb-2">{error}</p>}

        <VoiceInput
          language={user?.preferred_language || 'Hindi'}
          label="Ask by voice"
          showLanguagePicker={false}
          onTranscript={(t) => setInput((current) => (current ? `${current} ${t}` : t))}
          className="mb-2"
        />

        <div className="flex gap-2">
          <input
            className="flex-1 p-3 rounded-full border border-gray-300 text-base"
            placeholder="Type or speak your question..."
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && sendMessage()}
          />
          <button
            onClick={() => sendMessage()}
            disabled={loading}
            className="bg-terracotta text-white px-5 rounded-full font-semibold disabled:opacity-60"
          >
            {loading ? '...' : 'Send'}
          </button>
        </div>
      </div>
    </div>
  )
}

import { useState } from 'react'
import ProductPicker from '../components/ProductPicker.jsx'
import VoiceInput from '../components/VoiceInput.jsx'
import { generateCatalogue, updateProduct } from '../services/api.js'
import { useAuth } from '../services/AuthContext.jsx'

export default function Catalogue() {
  const { token, user } = useAuth()
  const language = user?.preferred_language || 'Hindi'

  const [product, setProduct] = useState(null)
  const [rawText, setRawText] = useState('')

  const [result, setResult] = useState(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [saved, setSaved] = useState(false)

  // Speech arrives phrase by phrase, so we add to what is already there
  // instead of overwriting it.
  function appendSpoken(text) {
    setRawText((current) => (current ? `${current} ${text}` : text))
  }

  async function handleGenerate() {
    if (!rawText.trim()) {
      setError('Please speak or type something about your product first.')
      return
    }
    setError('')
    setLoading(true)
    try {
      const data = await generateCatalogue(
        {
          raw_text: rawText,
          product_name: product?.name,
          category: product?.category,
          material: product?.material,
          craft_type: product?.craft_type,
          language,
        },
        token
      )
      setResult(data)
      setSaved(false)
    } catch (err) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  function updateField(field, value) {
    setResult({ ...result, [field]: value })
  }

  async function handleSave() {
    if (!result || !product) return
    setLoading(true)
    setError('')
    try {
      const formData = new FormData()
      formData.append('name', result.title_english || product.name)
      formData.append('name_hindi', result.title_hindi || product.name_hindi || '')
      formData.append('description_english', result.description_english || '')
      formData.append('description_hindi', result.description_hindi || '')
      formData.append('material', result.material || product.material || '')
      formData.append('category', result.category || product.category || '')
      formData.append('craft_type', product.craft_type || '')
      formData.append('price', product.price ?? '')
      formData.append('status', product.status)

      const updated = await updateProduct(product.id, formData, token)
      setProduct(updated)
      setSaved(true)
    } catch (err) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  const inputClass = 'w-full p-3 rounded-lg border border-gray-300 focus:border-forest focus:outline-none text-base'
  const labelClass = 'block text-sm font-medium text-charcoal mb-1 mt-4'

  return (
    <div>
      <ProductPicker selectedId={product?.id} onSelect={(p) => { setProduct(p); setResult(null) }} />

      {product && (
        <div className="p-5">
          <div className="bg-white rounded-xl p-4 shadow-sm mb-4">
            <p className="text-sm font-medium text-charcoal mb-2">
              🎙️ Speak about your product — no typing needed
            </p>
            <VoiceInput
              language={language}
              label="Speak About Your Product"
              onTranscript={appendSpoken}
              className="mb-3"
            />

            <label className={labelClass}>⌨️ Type About Your Product</label>
            <textarea
              className={inputClass}
              rows={4}
              value={rawText}
              onChange={(e) => setRawText(e.target.value)}
              placeholder="Or type here in Hindi, Hinglish or English..."
            />

            {error && <p className="text-red-600 text-sm mt-3">{error}</p>}

            <button
              onClick={handleGenerate}
              disabled={loading}
              className="w-full bg-terracotta text-white font-semibold py-3 rounded-full mt-4 shadow-md disabled:opacity-60"
            >
              {loading ? 'Generating catalogue...' : '✨ Create Catalogue with AI'}
            </button>
          </div>

          {result && (
            <div className="bg-white rounded-xl p-4 shadow-sm">
              <div className="flex items-center justify-between mb-3">
                <h3 className="font-semibold text-forest">Review &amp; Edit</h3>
                <span className={`text-xs font-semibold px-2 py-1 rounded-full ${result.ai_mode === 'real' ? 'bg-forest text-white' : 'bg-sand text-charcoal'}`}>
                  {result.ai_mode === 'real' ? `${result.ai_provider_label || 'AI'} Generated` : 'Demo Mode'}
                </span>
              </div>
              {result.ai_mode !== 'real' && (
                <p className="text-xs text-gray-500 mb-3">
                  No AI API key is configured yet, so this is a template-based draft, not a real
                  AI translation — please review the text carefully before publishing.
                </p>
              )}

              <label className={labelClass}>Title (English)</label>
              <input className={inputClass} value={result.title_english || ''} onChange={(e) => updateField('title_english', e.target.value)} />

              <label className={labelClass}>Title ({language})</label>
              <input className={inputClass} value={result.title_hindi || ''} onChange={(e) => updateField('title_hindi', e.target.value)} />

              <label className={labelClass}>Description (English)</label>
              <textarea className={inputClass} rows={3} value={result.description_english || ''} onChange={(e) => updateField('description_english', e.target.value)} />

              <label className={labelClass}>Description ({language})</label>
              <textarea className={inputClass} rows={3} value={result.description_hindi || ''} onChange={(e) => updateField('description_hindi', e.target.value)} />

              <label className={labelClass}>Key Features</label>
              <p className="text-sm text-gray-700 bg-ivory rounded-lg p-3">{(result.features || []).join(' • ')}</p>

              <label className={labelClass}>Marketing Caption</label>
              <input className={inputClass} value={result.marketing_caption || ''} onChange={(e) => updateField('marketing_caption', e.target.value)} />

              <label className={labelClass}>Social Media Caption</label>
              <input className={inputClass} value={result.social_caption || ''} onChange={(e) => updateField('social_caption', e.target.value)} />

              {saved && <p className="text-forest text-sm mt-3">Saved to product ✓</p>}

              <button
                onClick={handleSave}
                disabled={loading}
                className="w-full bg-forest text-white font-semibold py-3 rounded-full mt-4 shadow-md disabled:opacity-60"
              >
                {loading ? 'Saving...' : 'Save to Product'}
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

import { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import { useAuth } from '../services/AuthContext.jsx'
import { listProducts, getReadiness, getBusinessInsight, imageUrl } from '../services/api.js'
import CategoryBanner from '../components/CategoryBanner.jsx'
import { CATEGORY_THEMES } from '../theme/categoryTheme.js'

// Every feature the app offers, each with its own accent colour and a
// one-line description. This single list drives both the "stories" style
// quick-access strip and the "Explore ShilpSetu" grid below it, so the
// dashboard stays in sync automatically if a feature is ever added.
const FEATURES = [
  { to: '/products', label: 'My Products', icon: '📦', color: '#C96B4B', desc: 'Add, edit and manage your listings' },
  { to: '/photo-studio', label: 'Photo Studio', icon: '📷', color: '#6E4A8E', desc: 'AI-enhance your product photos' },
  { to: '/catalogue', label: 'AI Catalogue', icon: '📝', color: '#B5533C', desc: 'Auto-write titles & descriptions' },
  { to: '/pricing', label: 'Smart Pricing', icon: '💰', color: '#B8923F', desc: 'Fair, cost-based price suggestions' },
  { to: '/business-manager', label: 'AI Manager', icon: '💬', color: '#1F4D3A', desc: 'Ask about product, business or budget' },
  { to: '/digitalise', label: 'Digitalise', icon: '🌐', color: '#4C7A4F', desc: 'Step-by-step to go fully online' },
  { to: '/my-store', label: 'My Store', icon: '🏪', color: '#A83D5E', desc: 'Your public storefront & QR code' },
  { to: '/market-linkage', label: 'Market Linkage', icon: '🔗', color: '#71706B', desc: 'Discover buyers & opportunities' },
]

function StoryCircle({ feature }) {
  return (
    <Link to={feature.to} className="flex flex-col items-center gap-1 flex-shrink-0 w-16">
      <span
        className="w-14 h-14 rounded-full flex items-center justify-center p-[3px]"
        style={{ background: `linear-gradient(135deg, ${feature.color}, ${feature.color}55)` }}
      >
        <span className="w-full h-full rounded-full bg-ivory flex items-center justify-center text-2xl">
          {feature.icon}
        </span>
      </span>
      <span className="text-[10px] text-center leading-tight text-charcoal truncate w-16">{feature.label}</span>
    </Link>
  )
}

function FeatureCard({ feature, badge }) {
  return (
    <Link to={feature.to} className="fade-in bg-white rounded-2xl p-4 shadow-sm flex flex-col gap-2 active:scale-95 transition">
      <span
        className="w-11 h-11 rounded-xl flex items-center justify-center text-xl text-white"
        style={{ backgroundColor: feature.color }}
      >
        {feature.icon}
      </span>
      <span className="text-sm font-semibold text-charcoal">{feature.label}</span>
      <span className="text-xs text-gray-500 leading-snug">{feature.desc}</span>
      {badge && (
        <span
          className="text-[10px] font-semibold text-white px-2 py-0.5 rounded-full self-start"
          style={{ backgroundColor: feature.color }}
        >
          {badge}
        </span>
      )}
    </Link>
  )
}

// A single card in the continuously-scrolling "Discover" strip - a small
// coloured banner per feature, always in motion (see .marquee-track in
// index.css) so the dashboard never looks like a static page of links.
function FeatureBannerCard({ feature }) {
  return (
    <Link
      to={feature.to}
      className="relative w-44 h-24 rounded-2xl overflow-hidden flex-shrink-0 flex flex-col justify-end p-3 text-white shadow-sm"
      style={{ background: `linear-gradient(135deg, ${feature.color} 0%, ${feature.color}bb 100%)` }}
    >
      <span aria-hidden="true" className="absolute -right-2 -top-3 text-5xl opacity-25 select-none">
        {feature.icon}
      </span>
      <span className="relative text-sm font-semibold leading-tight">{feature.label}</span>
      <span className="relative text-[10px] opacity-90 leading-snug mt-0.5">{feature.desc}</span>
    </Link>
  )
}

// The "proactive AI" card - unlike every other AI feature in the app,
// nobody has to ask it anything. It quietly looks at the artisan's real
// data (product count, drafts, prices, readiness score) and surfaces one
// specific, useful observation the moment the dashboard loads. Fetched
// separately from the rest of the dashboard's data (its own loading
// state) since a live AI call can take a beat longer than the plain
// product/readiness lookups, and the rest of the page shouldn't wait on it.
function InsightCard({ insight, loading }) {
  if (loading) {
    return (
      <div className="bg-white rounded-2xl p-4 shadow-sm mb-6 flex gap-3 items-start">
        <div className="skeleton w-9 h-9 rounded-full flex-shrink-0" />
        <div className="flex-1 space-y-2 pt-1">
          <div className="skeleton h-3 rounded-full w-3/4" />
          <div className="skeleton h-3 rounded-full w-1/2" />
        </div>
      </div>
    )
  }
  if (!insight?.tip) return null
  return (
    <div
      className="fade-in rounded-2xl p-4 shadow-sm mb-6 flex gap-3 items-start text-white"
      style={{ background: 'linear-gradient(135deg, #1F4D3A 0%, #4C7A4F 100%)' }}
    >
      <span
        aria-hidden="true"
        className="w-9 h-9 rounded-full bg-white/20 flex items-center justify-center text-lg flex-shrink-0"
      >
        ✨
      </span>
      <div className="flex-1">
        <p className="text-[10px] uppercase tracking-wide text-white/70 font-semibold mb-1">
          AI Insight {insight.ai_mode === 'demo' ? '· Demo Mode' : insight.ai_provider_label ? `· ${insight.ai_provider_label}` : ''}
        </p>
        <p className="text-sm leading-snug">{insight.tip}</p>
      </div>
    </div>
  )
}

export default function Dashboard() {
  const { user, token } = useAuth()
  const [stats, setStats] = useState({ total: 0, published: 0, draft: 0 })
  const [recentProducts, setRecentProducts] = useState([])
  const [readiness, setReadiness] = useState(null)
  const [loading, setLoading] = useState(true)
  const [insight, setInsight] = useState(null)
  const [insightLoading, setInsightLoading] = useState(true)

  useEffect(() => {
    Promise.all([listProducts(token), getReadiness(token)])
      .then(([products, readinessData]) => {
        setStats({
          total: products.length,
          published: products.filter((p) => p.status === 'published').length,
          draft: products.filter((p) => p.status === 'draft').length,
        })
        // Most-recently-added first, for a small "what have I been working on" reel.
        setRecentProducts([...products].reverse().slice(0, 6))
        setReadiness(readinessData)
      })
      .catch(() => {})
      .finally(() => setLoading(false))

    getBusinessInsight(token)
      .then(setInsight)
      .catch(() => setInsight(null))
      .finally(() => setInsightLoading(false))
  }, [token])

  // Badges turn the static feature grid into a "dynamic dashboard" - each
  // tile reflects the artisan's own real data instead of just being a link.
  function badgeFor(feature) {
    if (loading) return null
    if (feature.to === '/products') {
      return stats.total ? `${stats.total} item${stats.total === 1 ? '' : 's'}` : 'Add your first'
    }
    if (feature.to === '/my-store') {
      return stats.published ? `${stats.published} live` : null
    }
    if (feature.to === '/digitalise' && readiness) {
      return `${readiness.score}% ready`
    }
    return null
  }

  return (
    <div>
      <CategoryBanner category={user?.business?.craft_category} className="px-5 py-6 mb-5">
        <h2 className="text-xl font-bold text-white mb-1">
          Welcome, {user?.name || 'Artisan'} 👋
        </h2>
        <p className="text-white/85">{user?.business?.business_name}</p>
        {user?.business?.craft_category && (
          <p className="text-white/70 text-xs mt-1">{user.business.craft_category}</p>
        )}
      </CategoryBanner>

      <div className="px-5">
        <InsightCard insight={insight} loading={insightLoading} />

        <p className="text-xs uppercase tracking-wide text-gray-400 mb-3">Discover what you can do</p>
        <div className="overflow-hidden mb-6">
          <div className="flex gap-3 marquee-track">
            {[...FEATURES, ...FEATURES].map((f, i) => (
              <FeatureBannerCard key={`${f.to}-${i}`} feature={f} />
            ))}
          </div>
        </div>

        <p className="text-xs uppercase tracking-wide text-gray-400 mb-3">Quick access</p>
        <div className="flex gap-3 overflow-x-auto pb-2 -mx-1 px-1 mb-6 no-scrollbar">
          {FEATURES.map((f) => (
            <StoryCircle key={f.to} feature={f} />
          ))}
        </div>

        <div className="grid grid-cols-3 gap-3 mb-6">
          {loading ? (
            [0, 1, 2].map((i) => (
              <div key={i} className="bg-white rounded-xl p-3 shadow-sm text-center">
                <div className="skeleton h-7 rounded-lg mx-auto w-10 mb-2" />
                <div className="skeleton h-3 rounded-full mx-auto w-12" />
              </div>
            ))
          ) : (
            <>
              <div className="fade-in bg-white rounded-xl p-3 shadow-sm text-center">
                <p className="text-2xl font-bold text-forest">{stats.total}</p>
                <p className="text-xs text-gray-500 mt-1">Products</p>
              </div>
              <div className="fade-in bg-white rounded-xl p-3 shadow-sm text-center">
                <p className="text-2xl font-bold text-forest">{stats.published}</p>
                <p className="text-xs text-gray-500 mt-1">Published</p>
              </div>
              <div className="fade-in bg-white rounded-xl p-3 shadow-sm text-center">
                <p className="text-2xl font-bold text-forest">{stats.draft}</p>
                <p className="text-xs text-gray-500 mt-1">Drafts</p>
              </div>
            </>
          )}
        </div>

        <div className="bg-white rounded-xl p-4 shadow-sm mb-6">
          <p className="text-sm text-gray-500 mb-1">Digital Readiness Score</p>
          {loading ? (
            <div className="skeleton h-8 rounded-lg w-20 mt-1" />
          ) : (
            <p className="fade-in text-3xl font-bold text-terracotta">{`${readiness?.score ?? 0}%`}</p>
          )}

          {readiness && (
            <div className="mt-3 space-y-1">
              {readiness.checklist.map((c) => (
                <p key={c.label} className="text-xs flex items-center gap-2">
                  <span>{c.done ? '✅' : '⬜'}</span>
                  <span className={c.done ? 'text-gray-500' : 'text-charcoal'}>{c.label}</span>
                </p>
              ))}
            </div>
          )}
          {readiness?.next_steps?.length > 0 && (
            <p className="text-xs text-gray-400 mt-3">
              Complete these {readiness.next_steps.length} step(s) to improve your score.
            </p>
          )}
        </div>

        {recentProducts.length > 0 && (
          <>
            <div className="flex items-center justify-between mb-3">
              <h3 className="font-semibold text-charcoal">Recent Products</h3>
              <Link to="/products" className="text-xs text-forest font-medium">See all</Link>
            </div>
            <div className="flex gap-3 overflow-x-auto pb-2 -mx-1 px-1 mb-6 no-scrollbar">
              {recentProducts.map((p) => {
                const theme = CATEGORY_THEMES[p.category] || CATEGORY_THEMES.Other
                return (
                  <Link key={p.id} to="/products" className="fade-in w-28 flex-shrink-0 bg-white rounded-xl shadow-sm overflow-hidden">
                    {p.image_url ? (
                      <img src={imageUrl(p.image_url)} alt={p.name} className="w-full h-28 object-cover" />
                    ) : (
                      <div className="w-full h-28 flex items-center justify-center text-3xl" style={{ backgroundColor: theme.color }}>
                        {theme.emoji}
                      </div>
                    )}
                    <div className="p-2">
                      <p className="text-xs font-medium text-charcoal truncate">{p.name}</p>
                      {p.price != null && <p className="text-[11px] text-terracotta font-semibold">₹{p.price}</p>}
                    </div>
                  </Link>
                )
              })}
            </div>
          </>
        )}

        <h3 className="font-semibold text-charcoal mb-3">Explore ShilpSetu</h3>
        <div className="grid grid-cols-2 gap-3">
          {FEATURES.map((f) => (
            <FeatureCard key={f.to} feature={f} badge={badgeFor(f)} />
          ))}
        </div>
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import { getMyStorefront, updateStorefront, uploadLogo, imageUrl } from '../services/api.js'
import { useAuth } from '../services/AuthContext.jsx'

export default function Digitalise() {
  const { token } = useAuth()
  const [business, setBusiness] = useState(null)
  const [form, setForm] = useState({ whatsapp_number: '', instagram_url: '', facebook_url: '' })
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')
  const [saved, setSaved] = useState(false)

  useEffect(() => {
    getMyStorefront(token)
      .then((b) => {
        setBusiness(b)
        setForm({
          whatsapp_number: b.whatsapp_number || '',
          instagram_url: b.instagram_url || '',
          facebook_url: b.facebook_url || '',
        })
      })
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false))
  }, [token])

  function handleChange(e) {
    setForm({ ...form, [e.target.name]: e.target.value })
    setSaved(false)
  }

  async function handleLogoChange(e) {
    const file = e.target.files?.[0]
    if (!file) return
    setSaving(true)
    setError('')
    try {
      const updated = await uploadLogo(file, token)
      setBusiness(updated)
    } catch (err) {
      setError(err.message)
    } finally {
      setSaving(false)
    }
  }

  async function handleSave() {
    setSaving(true)
    setError('')
    try {
      const updated = await updateStorefront(form, token)
      setBusiness(updated)
      setSaved(true)
    } catch (err) {
      setError(err.message)
    } finally {
      setSaving(false)
    }
  }

  async function togglePublish() {
    setSaving(true)
    try {
      const updated = await updateStorefront({ is_published: !business.is_published }, token)
      setBusiness(updated)
    } catch (err) {
      setError(err.message)
    } finally {
      setSaving(false)
    }
  }

  const inputClass = 'w-full p-3 rounded-lg border border-gray-300 focus:border-forest focus:outline-none text-base'
  const labelClass = 'block text-sm font-medium text-charcoal mb-1 mt-4'

  if (loading) return <p className="text-gray-500 p-5 text-center">Loading...</p>
  if (!business) return <p className="text-red-600 p-5 text-center">{error}</p>

  return (
    <div className="p-5">
      <div className="bg-white rounded-xl p-4 shadow-sm mb-4 text-center">
        <p className="text-sm text-gray-500">Your store is currently</p>
        <p className={`text-lg font-bold ${business.is_published ? 'text-forest' : 'text-gray-400'}`}>
          {business.is_published ? '✅ Live & Public' : '⏸ Not Published'}
        </p>
        <button
          onClick={togglePublish}
          disabled={saving}
          className={`mt-2 px-4 py-2 rounded-full text-sm font-semibold ${
            business.is_published ? 'border border-red-400 text-red-500' : 'bg-forest text-white'
          }`}
        >
          {business.is_published ? 'Unpublish Store' : 'Publish Store'}
        </button>
      </div>

      <div className="bg-white rounded-xl p-4 shadow-sm">
        <label className="block text-sm font-medium text-charcoal mb-1">Business Logo</label>
        {business.logo_url && (
          <img src={imageUrl(business.logo_url)} alt="Logo" className="w-20 h-20 object-cover rounded-full mb-2" />
        )}
        <input type="file" accept="image/jpeg,image/png,image/webp" onChange={handleLogoChange} className="text-sm" />

        <label className={labelClass}>WhatsApp Number (shown publicly)</label>
        <input className={inputClass} name="whatsapp_number" value={form.whatsapp_number} onChange={handleChange} placeholder="e.g. 9876543210" />

        <label className={labelClass}>Instagram Link</label>
        <input className={inputClass} name="instagram_url" value={form.instagram_url} onChange={handleChange} placeholder="https://instagram.com/yourbusiness" />

        <label className={labelClass}>Facebook Link</label>
        <input className={inputClass} name="facebook_url" value={form.facebook_url} onChange={handleChange} placeholder="https://facebook.com/yourbusiness" />

        {error && <p className="text-red-600 text-sm mt-3">{error}</p>}
        {saved && <p className="text-forest text-sm mt-3">Saved ✓</p>}

        <button
          onClick={handleSave}
          disabled={saving}
          className="w-full bg-terracotta text-white font-semibold py-3 rounded-full mt-4 shadow-md disabled:opacity-60"
        >
          {saving ? 'Saving...' : 'Save Changes'}
        </button>
      </div>

      <Link
        to="/my-store"
        className="block text-center w-full bg-forest text-white font-semibold py-3 rounded-full mt-4 shadow-md"
      >
        View My Digital Store →
      </Link>
    </div>
  )
}

import { useState } from 'react'
import { useNavigate, Link } from 'react-router-dom'
import { requestSecurityQuestion, resetPassword } from '../services/api.js'

/**
 * Password recovery in three small steps, so a user with low digital
 * confidence is never shown more than one thing to do at a time:
 *   1. "phone"    - type the phone number you registered with
 *   2. "answer"   - answer your own security question + choose a new password
 *   3. "done"     - confirmation, with a link back to login
 */
export default function ForgotPassword() {
  const [step, setStep] = useState('phone')
  const [phone, setPhone] = useState('')
  const [question, setQuestion] = useState(null)
  const [answer, setAnswer] = useState('')
  const [newPassword, setNewPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const navigate = useNavigate()

  async function handlePhoneSubmit(e) {
    e.preventDefault()
    setError('')
    setLoading(true)
    try {
      const data = await requestSecurityQuestion(phone)
      setQuestion(data)
      setStep('answer')
    } catch (err) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  async function handleResetSubmit(e) {
    e.preventDefault()
    setError('')

    if (newPassword.length < 6) {
      setError('Your new password must be at least 6 characters.')
      return
    }
    if (newPassword !== confirmPassword) {
      setError('The two passwords do not match.')
      return
    }

    setLoading(true)
    try {
      await resetPassword({ phone, answer, new_password: newPassword })
      setStep('done')
    } catch (err) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  const inputClass =
    'w-full p-3 rounded-lg border border-gray-300 focus:border-forest focus:outline-none text-base'
  const labelClass = 'block text-sm font-medium text-charcoal mb-1 mt-4'

  return (
    <div className="min-h-screen bg-ivory flex flex-col justify-center px-6 py-10">
      <div className="text-5xl text-center mb-2">🔑</div>
      <h1 className="text-2xl font-bold text-forest text-center mb-1">Forgot your password?</h1>

      {/* ---------- Step 1: phone number ---------- */}
      {step === 'phone' && (
        <>
          <p className="text-gray-600 text-center mb-4">
            Enter your registered phone number and we will ask you your
            security question.
          </p>
          <form onSubmit={handlePhoneSubmit}>
            <label className={labelClass}>Phone Number</label>
            <input
              className={inputClass}
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              placeholder="The number you registered with"
              required
            />

            {error && <p className="text-red-600 text-sm mt-4">{error}</p>}

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-forest text-white font-semibold py-3 rounded-full mt-6 shadow-md disabled:opacity-60"
            >
              {loading ? 'Checking...' : 'Continue'}
            </button>
          </form>
        </>
      )}

      {/* ---------- Step 2: answer + new password ---------- */}
      {step === 'answer' && question && (
        <>
          <p className="text-gray-600 text-center mb-4">
            Answer your security question to set a new password.
          </p>

          <div className="bg-white rounded-xl p-4 shadow-sm border border-gray-200">
            <p className="font-medium text-charcoal">{question.question_en}</p>
            <p className="text-sm text-gray-500 mt-1">{question.question_hi}</p>
          </div>

          <form onSubmit={handleResetSubmit}>
            <label className={labelClass}>Your answer</label>
            <input
              className={inputClass}
              value={answer}
              onChange={(e) => setAnswer(e.target.value)}
              placeholder="Write your answer"
              required
            />
            <p className="text-xs text-gray-500 mt-1">
              Capital letters and extra spaces do not matter.
            </p>

            <label className={labelClass}>New Password</label>
            <input
              className={inputClass}
              type="password"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              placeholder="At least 6 characters"
              required
            />

            <label className={labelClass}>Confirm New Password</label>
            <input
              className={inputClass}
              type="password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              required
            />

            {error && <p className="text-red-600 text-sm mt-4">{error}</p>}

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-terracotta text-white font-semibold py-3 rounded-full mt-6 shadow-md disabled:opacity-60"
            >
              {loading ? 'Saving...' : 'Set New Password'}
            </button>
          </form>

          <button
            type="button"
            onClick={() => { setStep('phone'); setError(''); setAnswer('') }}
            className="w-full text-gray-600 underline mt-4"
          >
            Use a different phone number
          </button>
        </>
      )}

      {/* ---------- Step 3: success ---------- */}
      {step === 'done' && (
        <>
          <div className="text-5xl text-center mt-4 mb-2">✅</div>
          <p className="text-center text-gray-700 mb-6">
            Your password has been changed. You can now log in with your new
            password.
          </p>
          <button
            onClick={() => navigate('/login')}
            className="w-full bg-forest text-white font-semibold py-3 rounded-full shadow-md"
          >
            Go to Login
          </button>
        </>
      )}

      <p className="text-center mt-6 text-gray-600">
        Remembered it?{' '}
        <Link to="/login" className="text-forest font-medium underline">Log in</Link>
      </p>
    </div>
  )
}

